GLB_InitSystem (
CHAR  *exepath,      // INPUT: Where program was run from
INT   innum,         // INPUT: MAX .GLB FILES TO LOOK FOR
CHAR  *iprefix       // INPUT: FILENAME PREFIX ( NULL for "FILE" )
)
{
	int			opened;
	int			filenum;
