/***************************************************************************
   Rot_Color () - Rotates color in palette
 ***************************************************************************/
VOID
Rot_Color (
BYTE *gpal,
INT snum,
INT len
)
{
   short pos, maxloop;
   char h1[3];
  
   pos = snum*3;
   maxloop=len*3;
  
   memcpy ( h1, gpal + pos, 3 );
   memcpy ( gpal + pos, gpal + pos + 3, maxloop );
   memcpy ( gpal + pos + maxloop - 3, h1, 3 );
}
  
