Do_Game () - The main game thing this is it dude
 ***************************************************************************/
BOOL           // TRUE=Aborted, FALSE = timeout
Do_Game (
VOID
)
{
   volatile INT  local_cnt;
   BOOL          b2_flag      = FALSE;
   BOOL          b3_flag      = FALSE;
   BOOL          init_flag    = TRUE;
   BOOL          rval         = FALSE;
   INT           start_score  = 0;

   draw_player = TRUE;

   srand ( ( 1024 * game_wave [ cur_game ] ) );

   fadeflag = FALSE;
   end_fadeflag = FALSE;
   KBD_Clear();
   IMS_StartAck();
   BUT_1 = FALSE;
   BUT_2 = FALSE;
   BUT_3 = FALSE;
   BUT_4 = FALSE;
  
