   local_cnt = FRAME_COUNT;
  
   g_flash = 0;
   g_oldsuper     = EMPTY;
   g_oldshield    = EMPTY;
   startendwave   = EMPTY;

   if ( demo_flag == DEMO_RECORD )
      DEMO_StartRec();

   // == CLEAR ALL BUTTONS ===========================

   start_score = plr.score;
   IMS_StartAck();
   memset ( buttons, 0, sizeof ( buttons ) );

   for (;;)
   {
      SHADOW_Clear();
  
      IPT_MovePlayer();
  
      if ( KBD_IsKey ( SC_F1 ) )
      {
         SWD_SetClearFlag ( FALSE );
         IPT_End();
         HELP_Win ( "OVERVW06_TXT" );
         memset ( displayscreen, 0, 64000 );
         IPT_Start();
         g_oldsuper = EMPTY;
         g_oldshield = EMPTY;
         RAP_ClearSides();
         RAP_DisplayStats();
         SWD_SetClearFlag ( TRUE );
         IMS_StartAck();
         BUT_1 = FALSE;
         BUT_2 = FALSE;
         BUT_3 = FALSE;
         BUT_4 = FALSE;
         b2_flag = FALSE;
         b3_flag = FALSE;
      }

      if ( KBD_IsKey ( SC_P ) )
      {
         while ( IMS_IsAck() );
         SWD_SetClearFlag ( FALSE );
         RAP_ClearSides();
         WIN_Pause();
         g_oldsuper = EMPTY;
         g_oldshield = EMPTY;
         RAP_ClearSides();
         RAP_DisplayStats();
         SWD_SetClearFlag ( TRUE );
         IMS_StartAck();
         BUT_1 = FALSE;
         BUT_2 = FALSE;
         BUT_3 = FALSE;
         BUT_4 = FALSE;
         b2_flag = FALSE;
         b3_flag = FALSE;
      }

      if ( KBD_IsKey ( SC_F8 ) && godmode )
      {
         while ( IMS_IsAck() );
         debugflag ^= TRUE;
      }

      if ( DEMO_Think() )
         break;

      if ( demo_mode  == DEMO_PLAYBACK )
      {
         if ( IMS_IsAck () && !BUT_2 && !BUT_3 && !BUT_4 )
         {
            rval = TRUE;
            break;
         }
      }

      switch ( KBD_LASTSCAN )
      {
         case SC_NONE:
            break;

         default:
            break;

         case SC_1:
            OBJS_MakeSpecial ( S_DUMB_MISSLE );
            break;

         case SC_2:
            OBJS_MakeSpecial ( S_MINI_GUN );
            break;

         case SC_3:
            OBJS_MakeSpecial ( S_TURRET );
            break;

         case SC_4:
            OBJS_MakeSpecial ( S_MISSLE_PODS );
            break;

         case SC_5:
            OBJS_MakeSpecial ( S_AIR_MISSLE  );
            break;

         case SC_6:
            OBJS_MakeSpecial ( S_GRD_MISSLE );
            break;

         case SC_7:
            OBJS_MakeSpecial ( S_BOMB );
            break;

         case SC_8:
            OBJS_MakeSpecial ( S_ENERGY_GRAB );
            break;

         case SC_9:
            OBJS_MakeSpecial ( S_PULSE_CANNON );
            break;

         case SC_0:
            OBJS_MakeSpecial ( S_DEATH_RAY );
            break;

         case SC_MINUS:
            OBJS_MakeSpecial ( S_FORWARD_LASER );
            break;
      }

      if ( BUT_1 )
      {
         OBJS_Use ( S_FORWARD_GUNS );
         OBJS_Use ( S_PLASMA_GUNS );
         OBJS_Use ( S_MICRO_MISSLE );
         BUT_1 = FALSE;
         if ( plr.sweapon != EMPTY )
            OBJS_Use ( plr.sweapon );
      }
  
      if ( BUT_2 )
      {
