            IMS_StartAck();
            BUT_1 = FALSE;
            BUT_2 = FALSE;
            BUT_3 = FALSE;
            BUT_4 = FALSE;
            b2_flag = FALSE;
            b3_flag = FALSE;
         }
         else if ( demo_mode == DEMO_PLAYBACK )
         {
            rval = TRUE;
            break;
         }
         else if ( demo_mode == DEMO_RECORD )
