/***************************************************************************
 RAP_LoadMap () - Loads A level Map
 ***************************************************************************/
VOID
RAP_LoadMap (
VOID
)
{
   CHAR           temp[42];

   if ( !gameflag [ cur_game ] )
      EXIT_Error ("Loading Invalid map game %d", cur_game );

   GLB_FreeAll();

   sprintf ( temp, "MAP%uG%u_MAP", game_wave [ cur_game ] + 1, cur_game + 1 );
   map_item = GLB_GetItemID ( temp );

   if ( map_item == EMPTY )
      EXIT_Error ("RAP_LoadMap() - Invalid MAP.(%s)", temp );

   mapmem = GLB_LockItem ( map_item );

   ml       = ( MAZELEVEL * ) mapmem;
   csprite  = ( CSPRITE * ) ( mapmem + sizeof ( MAZELEVEL ) );

   ENEMY_LoadLib();
   SND_CacheGFX();
   BONUS_Init();
   WIN_SetLoadLevel ( 20 );
   OBJS_CachePics();
   WIN_SetLoadLevel ( 40 );
   ANIMS_CachePics();
   WIN_SetLoadLevel ( 60 );
   ENEMY_LoadSprites();
   WIN_SetLoadLevel ( 80 );
   TILE_CacheLevel();
   WIN_SetLoadLevel ( 100 );
   WIN_EndLoad();
}

/***************************************************************************
RAP_FreeMap() - Frees up cached map stuff
 ***************************************************************************/
VOID
RAP_FreeMap (
VOID
)
{
   if ( map_item != EMPTY )
   {
      TILE_FreeLevel();
      ENEMY_FreeSprites();
      ANIMS_FreePics();
      OBJS_FreePics();
      SND_FreeFX();

      // FREE MAP ========================

      GLB_FreeItem ( map_item );

      map_item = EMPTY;
   }

   GLB_FreeAll();
   SND_CacheIFX();
}


