   SPRITE_SHIP * next;

   if ( sh->lib->bossflag )
      numboss--;

   numships--;

   if ( end_waveflag && numships < 1 )
      startendwave = END_DURATION;

   next = sh->prev;

   sh->next->prev = sh->prev;
   sh->prev->next = sh->next;

   memset ( sh, 0, sizeof ( SPRITE_SHIP ) );
   sh->item = ~0;

   sh->next = free_enemy;

   free_enemy = sh;

   return ( next );
